import type { NextRequest } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { priorRange } from '@/lib/analytics/range'
import type {
  NewClientsByMonthPoint,
  CohortRetentionRow,
  LtvBucket,
} from '@/lib/types/analytics'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

// LTV bucket definitions — min/max in cents, label for display
const LTV_BUCKETS: Array<{ bucket: string; min: number; max: number | null }> = [
  { bucket: '$0–100',   min: 0,       max: 10_000 },
  { bucket: '$100–500', min: 10_000,  max: 50_000 },
  { bucket: '$500–1k',  min: 50_000,  max: 100_000 },
  { bucket: '$1k–5k',   min: 100_000, max: 500_000 },
  { bucket: '$5k+',     min: 500_000, max: null },
]

interface ClientsBlock {
  totalClients: number
  newClients: number
  returningClients: number
  inactiveClients: number
  avgLtv: number
  retentionRate: number
  // Sprint 5 depth
  newClientsByMonth: NewClientsByMonthPoint[]
  cohortRetention: CohortRetentionRow[]
  ltvDistribution: LtvBucket[]
}

/** Format a Date into an ISO month key "YYYY-MM". */
function toMonthKey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
}

/** Format a month key into a display label "Jan 2026". */
function monthLabel(key: string): string {
  const [yr, mo] = key.split('-')
  const d = new Date(Number(yr), Number(mo) - 1, 1)
  return d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' })
}

/**
 * Build cohort retention table.
 *
 * Algorithm:
 *   - Trailing 12 months of cohorts (by client.created_at month)
 *   - For each cohort, compute retention[N] = % of cohort members who had
 *     at least one completed booking in cohort-month + N calendar months.
 *   - Cells where cohort+N is in the future are null.
 *
 * Uses a single all-bookings scan to avoid N+1 queries.
 * Future optimisation: push to a Postgres materialized view / RPC when row count > 50k.
 */
function buildCohortRetention(
  clients: Array<{ id: string; created_at: string }>,
  allBookings: Array<{ client_id: string | null; scheduled_at: string; status: string }>,
  nowKey: string,
): CohortRetentionRow[] {
  // Build set of cohort months: trailing 12
  const cohortMonths: string[] = []
  const nowDate = new Date()
  for (let i = 11; i >= 0; i--) {
    const d = new Date(nowDate.getFullYear(), nowDate.getMonth() - i, 1)
    cohortMonths.push(toMonthKey(d))
  }

  // Index clients by cohort month
  const cohortMap = new Map<string, Set<string>>()
  for (const c of clients) {
    const mKey = toMonthKey(new Date(c.created_at))
    if (!cohortMonths.includes(mKey)) continue
    if (!cohortMap.has(mKey)) cohortMap.set(mKey, new Set())
    cohortMap.get(mKey)!.add(c.id)
  }

  // Index completed bookings: clientId → Set of month keys they booked in
  const clientBookingMonths = new Map<string, Set<string>>()
  for (const b of allBookings) {
    if (!b.client_id || b.status !== 'completed') continue
    if (!clientBookingMonths.has(b.client_id)) {
      clientBookingMonths.set(b.client_id, new Set())
    }
    clientBookingMonths.get(b.client_id)!.add(toMonthKey(new Date(b.scheduled_at)))
  }

  return cohortMonths.map((cohortKey) => {
    const members = cohortMap.get(cohortKey) ?? new Set<string>()
    const cohortSize = members.size

    // Compute the calendar month for cohort+N (N = 1..6)
    const [yr, mo] = cohortKey.split('-').map(Number)
    const retentions: Array<number | null> = []
    for (let n = 1; n <= 6; n++) {
      const followDate = new Date(yr, (mo - 1) + n, 1)
      const followKey = toMonthKey(followDate)
      // Cell is in the future — not applicable
      if (followKey > nowKey) {
        retentions.push(null)
        continue
      }
      if (cohortSize === 0) {
        retentions.push(null)
        continue
      }
      let returned = 0
      for (const clientId of members) {
        if (clientBookingMonths.get(clientId)?.has(followKey)) returned++
      }
      retentions.push(Math.round((returned / cohortSize) * 100))
    }

    return {
      cohort: monthLabel(cohortKey),
      cohortKey,
      cohortSize,
      retentions,
    }
  })
}

async function fetchClientsData(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string | undefined,
  to: string | undefined,
): Promise<ClientsBlock> {
  const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()
  const nowKey = toMonthKey(new Date())

  // Fetch all clients + all-time bookings in parallel
  // All-time bookings needed for cohort retention (not scoped to the date window)
  const [allClients, allBookings, windowBookings] = await Promise.all([
    supabase.from('clients').select('id, created_at').eq('studio_id', studioId),
    // All-time completed bookings for cohort + LTV calculations
    supabase
      .from('bookings')
      .select('client_id, scheduled_at, status, price_cents, deposit_cents')
      .eq('studio_id', studioId)
      .in('status', ['completed', 'no_show']),
    // Window-scoped bookings for period KPIs
    supabase
      .from('bookings')
      .select('client_id, scheduled_at, price_cents, deposit_cents')
      .eq('studio_id', studioId)
      .eq('status', 'completed')
      .order('scheduled_at', { ascending: true })
      .then((r) => {
        if (!r.data) return r
        let filtered = r.data
        if (from) filtered = filtered.filter((b) => b.scheduled_at >= from)
        if (to) filtered = filtered.filter((b) => b.scheduled_at <= to)
        return { ...r, data: filtered }
      }),
  ])

  if (allClients.error) throw allClients.error
  if (allBookings.error) throw allBookings.error
  if (windowBookings.error) throw windowBookings.error

  const clients = allClients.data ?? []
  const bookingsAll = allBookings.data ?? []
  const bookingsWindow = windowBookings.data ?? []

  // ── Period-scoped KPIs ────────────────────────────────────────────────────
  const clientsInWindow = clients.filter((c) => {
    if (from && c.created_at < from) return false
    if (to && c.created_at > to) return false
    return true
  })
  const totalClients = clientsInWindow.length

  const clientSpendWindow = new Map<string, number>()
  const clientLastVisit = new Map<string, string>()
  for (const b of bookingsWindow) {
    if (!b.client_id) continue
    const rev = (b.price_cents ?? 0) + (b.deposit_cents ?? 0)
    clientSpendWindow.set(b.client_id, (clientSpendWindow.get(b.client_id) ?? 0) + rev)
    const prev = clientLastVisit.get(b.client_id)
    if (!prev || b.scheduled_at > prev) clientLastVisit.set(b.client_id, b.scheduled_at)
  }

  const returningClients = Array.from(clientSpendWindow.entries()).filter(([id]) => {
    return bookingsWindow.filter((b) => b.client_id === id).length > 1
  }).length
  const newClients = totalClients - returningClients
  const inactiveClients = Array.from(clientLastVisit.entries())
    .filter(([, last]) => last < ninetyDaysAgo).length

  const ltvValues = Array.from(clientSpendWindow.values())
  const avgLtv = ltvValues.length > 0
    ? Math.round(ltvValues.reduce((s, v) => s + v, 0) / ltvValues.length)
    : 0

  // ── New clients by month (trailing 12 months of all-time data) ────────────
  const monthCountMap = new Map<string, number>()
  for (const c of clients) {
    const mKey = toMonthKey(new Date(c.created_at))
    monthCountMap.set(mKey, (monthCountMap.get(mKey) ?? 0) + 1)
  }
  // Build trailing 12 month list regardless of data presence
  const newClientsByMonth: NewClientsByMonthPoint[] = []
  for (let i = 11; i >= 0; i--) {
    const d = new Date(new Date().getFullYear(), new Date().getMonth() - i, 1)
    const mKey = toMonthKey(d)
    newClientsByMonth.push({ month: mKey, count: monthCountMap.get(mKey) ?? 0 })
  }

  // ── Cohort retention ──────────────────────────────────────────────────────
  const cohortRetention = buildCohortRetention(clients, bookingsAll, nowKey)

  // ── LTV distribution (all-time spend per client) ──────────────────────────
  const clientLtv = new Map<string, number>()
  for (const b of bookingsAll) {
    if (!b.client_id || b.status !== 'completed') continue
    const rev = (b.price_cents ?? 0) + (b.deposit_cents ?? 0)
    clientLtv.set(b.client_id, (clientLtv.get(b.client_id) ?? 0) + rev)
  }
  const ltvDistribution: LtvBucket[] = LTV_BUCKETS.map((def) => {
    const count = Array.from(clientLtv.values()).filter((v) => {
      if (v < def.min) return false
      if (def.max !== null && v >= def.max) return false
      return true
    }).length
    return { ...def, count }
  })

  return {
    totalClients,
    newClients,
    returningClients,
    inactiveClients,
    avgLtv,
    retentionRate: totalClients > 0 ? Math.round((returningClients / totalClients) * 100) : 0,
    newClientsByMonth,
    cohortRetention,
    ltvDistribution,
  }
}

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const supabase = await createClient()
  const { from, to, compare } = parsed.data

  try {
    const current = await fetchClientsData(supabase, auth.studioId, from, to)

    if (compare !== '1' || !from || !to) {
      return Response.json({ current })
    }

    const prior = priorRange({ from, to })
    const priorData = await fetchClientsData(supabase, auth.studioId, prior.from, prior.to)

    return Response.json({ current, prior: priorData })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'clients report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

